"""Inspect the workspace and available tools for the PDF cover-page task."""
import os
import shutil
import sys

print(f"cwd: {os.getcwd()}")
print(f"python: {sys.executable} {sys.version.split()[0]}")
print("sys.path:")
for p in sys.path:
    print(f"  {p}")

print("\nworkspace listing:")
for name in sorted(os.listdir(".")):
    full = os.path.join(".", name)
    if os.path.isfile(full):
        print(f"  FILE {name} ({os.path.getsize(full)} bytes)")
    else:
        print(f"  DIR  {name}/")

if os.path.exists("report.pdf"):
    print(f"\nreport.pdf size: {os.path.getsize('report.pdf')} bytes")
    with open("report.pdf", "rb") as f:
        head = f.read(16)
    print(f"report.pdf first bytes: {head!r}")
else:
    print("\nreport.pdf NOT FOUND")

print("\ncommand-line tools:")
for tool in ["qpdf", "pdftk", "gs", "mutool", "pdftotext", "pdftoppm", "pdfimages", "python3", "pip", "pip3"]:
    path = shutil.which(tool)
    print(f"  {tool}: {path if path else 'not found'}")

# Check for any vendored site-packages next to the skill or workspace
for cand in [".codex/skills/pdf", ".codex/skills/pdf/scripts", "site-packages", ".venv", "venv"]:
    if os.path.isdir(cand):
        print(f"\ncontents of {cand}/:")
        for name in sorted(os.listdir(cand))[:100]:
            print(f"  {name}")

